def max_area(heights):
    kiri, kanan = 0, len(heights) - 1
    terbaik = 0
    while kiri < kanan:
        tinggi = min(heights[kiri], heights[kanan])
        terbaik = max(terbaik, tinggi * (kanan - kiri))
        if heights[kiri] < heights[kanan]:
            kiri += 1
        else:
            kanan -= 1
    return terbaik
